inline const Profile* FindProfile(FirmwareModel model, FirmwareEdition edition, uint16_t code = 0) {
    if (!code) code = FirmwareCanonicalCode(model);
    for (const auto& profile : Profiles)
        if (profile.model == model && profile.edition == edition && profile.code == code) return &profile;
    return nullptr;
}
